examples.code:
const prices = [120, 45, 300, 60, 15];

const big = prices.filter((p) => p >= 60);            // [120, 300, 60]
const withDiscount = big.map((p) => p - (p * 10) / 100); // минус 10% с каждой

document.body.append(withDiscount.join(', '));

const scores = [10, 9, 2];

const wrong = [...scores].sort();                // [10, 2, 9] — сортировка как строк!
const right = [...scores].sort((a, b) => a - b); // [2, 9, 10] — по возрастанию чисел

document.body.append(wrong.join(',') + ' против ' + right.join(','));

const cart = [250, 400, 100];

const total = cart.reduce((acc, price) => acc + price, 0); // 750
const expensive = cart.find((price) => price > 200);       // 250
const allCheap = cart.every((price) => price < 500);       // true

document.body.append(total + ' | ' + expensive + ' | ' + allCheap);

